const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  function getInfoAsync(obj) {
    return new Promise((resolve, reject) => {
      obj.getInfo((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });
  }

  // 1. Geometry & Time Definitions
  // Approximate centers for Todoque and El Paraíso, La Palma, Canary Islands
  const todoque = ee.Geometry.Point([-17.8829, 28.6093]);
  const pariso = ee.Geometry.Point([-17.8555, 28.6070]); // "El Paraíso" approximate
  const bufferMeters = 1500;
  const region = todoque.buffer(bufferMeters).union(pariso.buffer(bufferMeters));

  const preNarrow = ['2021-05-15', '2021-06-05'];
  const postNarrow = ['2021-12-10', '2021-12-20'];
  const preWide = ['2021-04-21', '2021-06-30'];
  const postWide = ['2021-11-15', '2021-12-31'];

  // 2. Data Acquisition & Check
  // Sentinel-2 masking
  function maskS2(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const maskQA = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    const scl = img.select('SCL');
    const sclMask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10)).and(scl.neq(11));
    return img.updateMask(maskQA).updateMask(sclMask);
  }

  // Landsat masking and scaling (L2)
  function maskLsL2(img) {
    const qa = img.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 3).eq(0);
    const cloudShadow = qa.bitwiseAnd(1 << 4).eq(0);
    const cirrus = qa.bitwiseAnd(1 << 2).eq(0);
    const mask = cloud.and(cloudShadow).and(cirrus);
    // Apply reflectance scaling
    const scaled = img
      .select(['SR_B5', 'SR_B7'], ['NIR', 'SWIR2'])
      .multiply(0.0000275).add(-0.2);
    return scaled.updateMask(mask);
  }

  function addNBR(img, nirName, swirName) {
    const nir = img.select(nirName);
    const swir = img.select(swirName);
    const nbr = nir.subtract(swir).divide(nir.add(swir)).rename('NBR');
    return img.addBands(nbr);
  }

  async function getS2Composite(start, end) {
    const col = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterDate(start, end)
      .filterBounds(region)
      .filter(ee.Filter.lte('CLOUDY_PIXEL_PERCENTAGE', 80))
      .map(maskS2)
      .select(['B8', 'B12'], ['NIR', 'SWIR2']);
    const size = await getInfoAsync(col.size());
    if (size === 0) return { img: null, size: 0, source: 'S2' };
    const med = col.median();
    const withNBR = addNBR(med, 'NIR', 'SWIR2');
    return { img: withNBR, size: size, source: 'S2' };
  }

  async function getLandsatComposite(start, end) {
    const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(start, end);
    const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(start, end);
    const col = l8.merge(l9)
      .filterBounds(region)
      .map(maskLsL2);
    const size = await getInfoAsync(col.size());
    if (size === 0) return { img: null, size: 0, source: 'Landsat' };
    const med = col.median();
    const withNBR = addNBR(med, 'NIR', 'SWIR2');
    return { img: withNBR, size: size, source: 'Landsat' };
  }

  async function getCompositeWithFallback(preOrPost) {
    const rangeNarrow = preOrPost === 'pre' ? preNarrow : postNarrow;
    const rangeWide = preOrPost === 'pre' ? preWide : postWide;

    // Try S2 narrow
    let res = await getS2Composite(rangeNarrow[0], rangeNarrow[1]);
    if (res.img) return { ...res, window: 'narrow' };

    // Try S2 wide
    res = await getS2Composite(rangeWide[0], rangeWide[1]);
    if (res.img) return { ...res, window: 'wide' };

    // Try Landsat narrow
    res = await getLandsatComposite(rangeNarrow[0], rangeNarrow[1]);
    if (res.img) return { ...res, window: 'narrow' };

    // Try Landsat wide
    res = await getLandsatComposite(rangeWide[0], rangeWide[1]);
    if (res.img) return { ...res, window: 'wide' };

    return { img: null, size: 0, source: 'None', window: 'none' };
  }

  const preComp = await getCompositeWithFallback('pre');
  const postComp = await getCompositeWithFallback('post');

  if (!preComp.img || !postComp.img) {
    console.log(`Pre images: ${preComp.size} (${preComp.source}, ${preComp.window}), Post images: ${postComp.size} (${postComp.source}, ${postComp.window})`);
    console.log('Empty collection for one or both periods.');
    console.log('C1');
    return;
  }

  // 3. Processing and Valid Pixel Checks
  const areaImgHa = ee.Image.pixelArea().divide(1e4).rename('area');

  function validCountAtScale(img) {
    // Count non-masked pixels of first band (NBR exists)
    const firstBand = img.bandNames().get(0);
    return img.select([firstBand]).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).values().get(0);
  }
  const totalCells = await getInfoAsync(
    ee.Image(1).rename('c').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('c')
  );
  const preValid = await getInfoAsync(validCountAtScale(preComp.img));
  const postValid = await getInfoAsync(validCountAtScale(postComp.img));

  if ((preValid === null || preValid === 0) || (postValid === null || postValid === 0)) {
    console.log(`Pre images: ${preComp.size} (${preComp.source}, ${preComp.window}), Post images: ${postComp.size} (${postComp.source}, ${postComp.window})`);
    console.log(`Valid px (1000m): Pre=${preValid || 0}/${totalCells}, Post=${postValid || 0}/${totalCells}`);
    console.log('No valid pixels after masking.');
    console.log('C2');
    return;
  }

  // 4. Calculation
  const preNBR = preComp.img.select('NBR');
  const postNBR = postComp.img.select('NBR');
  const dNBR = preNBR.subtract(postNBR).rename('dNBR');

  // Areas where lava likely present (very low NBR) and where strong change occurred (dNBR > 0.35)
  const preLavaMask = preNBR.lt(0.0);
  const postLavaMask = postNBR.lt(0.0);
  const dNBRMask = dNBR.gt(0.35);

  const regionAreaHa = await getInfoAsync(areaImgHa.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('area'));

  const preLavaHa = await getInfoAsync(areaImgHa.updateMask(preLavaMask).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('area'));

  const postLavaHa = await getInfoAsync(areaImgHa.updateMask(postLavaMask).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('area'));

  const dNBRHa = await getInfoAsync(areaImgHa.updateMask(dNBRMask).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('area'));

  const meanDNBR = await getInfoAsync(dNBR.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('dNBR'));

  // 5. Validation & Final Answer
  function invalid(x) {
    return x === null || x === undefined || (typeof x === 'number' && !isFinite(x));
  }
  if ([regionAreaHa, preLavaHa, postLavaHa, dNBRHa, meanDNBR].some(invalid)) {
    console.log('Calculation returned null/NaN.');
    console.log('C3');
    return;
  }

  const preImgsStr = `${preComp.size} (${preComp.source}, ${preComp.window})`;
  const postImgsStr = `${postComp.size} (${postComp.source}, ${postComp.window})`;
  const preValidPct = totalCells ? (100 * preValid / totalCells) : 0;
  const postValidPct = totalCells ? (100 * postValid / totalCells) : 0;
  const deltaHa = (postLavaHa || 0) - (preLavaHa || 0);

  // Evidence (<=20 lines)
  console.log(`AOI buffers: 1.5 km; Region area: ${regionAreaHa.toFixed(1)} ha`);
  console.log(`Pre images: ${preImgsStr}, Post images: ${postImgsStr}`);
  console.log(`Valid px (1000m): Pre=${preValid}/${totalCells} (${preValidPct.toFixed(0)}%), Post=${postValid}/${totalCells} (${postValidPct.toFixed(0)}%)`);
  console.log(`Pre lava area (NBR<0): ${Number(preLavaHa || 0).toFixed(2)} ha`);
  console.log(`Post lava area (NBR<0): ${Number(postLavaHa || 0).toFixed(2)} ha`);
  console.log(`Δ lava area: ${deltaHa.toFixed(2)} ha`);
  console.log(`dNBR>0.35 area: ${Number(dNBRHa || 0).toFixed(2)} ha, mean dNBR: ${Number(meanDNBR).toFixed(3)}`);

  const increased = deltaHa > 1; // require >1 ha increase to avoid noise
  console.log(increased ? 'A' : 'B');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  try {
    await runAnalysis();
  } catch (err) {
    console.log('D');
  }
}

initEE();
